      SUBROUTINE DERIVECC     MULTIPLIES R, T, AND U MATRICES AND THEIR DERIVATIVES FORC     THE ENTIRE SYSTEMCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM2D.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'ETAP.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'NELMS.CIN'      INCLUDE 'R.CIN'      INCLUDE 'R0P.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R2VS.CIN'      INCLUDE 'R3P.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'SVP.CIN'CC     LOCAL VARIABLESC      LOGICAL         VARLET, WOOF      INTEGER         VARST      REAL            COSS(6), COT(6), COTF(6), ETAS(6), ETAT(6)      EXTERNAL        IDATACC---------------------------------------------------------------      WOOF = SOFA      NWK = -1      CALL ELMENT(NWK)      IF (FLUSHL) GO TO 810      IF (TYPE .LE. 0) GO TO 810      IF (NWK .EQ. 1) GO TO 200      IF (TYPE .EQ. 1 .OR. TYPE .EQ. 7 .OR. TYPE .EQ. 8     1    .OR. TYPE .EQ. 27 .OR. TYPE .EQ. 43) GO TO 170      IF (TYPE .EQ. 12) GO TO 100      IF (CFIT) GO TO 200      GO TO 810CC     ELEMENTS AFFECTING THE BEAM MATRIX BUT HAVING NO TRANSFER MATRIXC  100 IF (NORD3 .LT. 1) GO TO 170      DO 120 N = 1, NV1      IF (SVP(N)) THEN        DO 110 J = 2, 6        JMIN1 = J - 1        DO 110 K = 1, JMIN1        DSV = 0.0        IF (SI(J,J) .NE. 0.0 .AND. SI(K,K) .NE. 0.0)     1      DSV = 0.5*SI(J,K)*(SV(J,J,N)/SI(J,J) + SV(K,K,N)/SI(K,K))        SV(J,K,N) = DSV        SV(K,J,N) = DSV  110   CONTINUE      ENDIF  120 CONTINUEC  170 NVTYPE = NV(TYPE)      IF (NVTYPE .EQ. 0) GO TO 810      DO 180 JV = 1, NVTYPE      IPT = IPTOJ(JV)      IF (IPT .EQ. 0) GO TO 180      IPLJV = I + IPT      IADR = IPLJV  172 NV2 = TIE(IADR)      IF (NV2 .EQ. 0) GO TO 180      IF (NV2 .EQ. 100) THEN        IADR = IDATA(IADR)        IF (NV2 .EQ. 100) GO TO 172      ENDIF      DPARM = 1.0      IF (NV2 .LT. 0) DPARM = - 1.0      NVP = 1      IF (NV2 .EQ. 99) NVP = NPVAR      DO 175 JP = 1, NVP      IF (NVP .EQ. NPVAR) THEN        NV2 = JP        DPARM = DATA(IADR + JP)        IF (DPARM .EQ. 0.0) GO TO 175      ENDIF      NV1 = MAX0(NV1,IABS(NV2))      CALL PARTLS  175 CONTINUE  180 CONTINUE      IF (TYPE .EQ. 43) GO TO 808      GO TO 810CC     ELEMENTS HAVING A TRANSFER MATRIXC  200 NVTYPE = NV(TYPE)      IF (.NOT. RMTX) GO TO 808CC     IS ANYTHING BEING VARIED?C      IF (NVTYPE .LT. 1) GO TO 215      DO 210 JV = 1, NVTYPE      NV2 = VARST(JV)      IF (NV2 .NE. 0 .AND. NV2 .NE. 99) THEN        GO TO 300      ELSE IF (NV2 .EQ. 99) THEN        IF (JV .LE. NELMS(TYPE)) THEN          IADR = I + IPTOJ(JV)          IADR = IDATA(IADR)        ELSE IF (TYPE .EQ. 2) THEN          IADR = IBVARY        ELSE          IADR = 0        ENDIF        DO 205 JP = 1, NV3        DPARM = DATA(IADR + JP)        IF (DPARM .NE. 0.0) GO TO 300  205   CONTINUE      ENDIF  210 CONTINUECC     IS THERE ANY IMPLICIT ELEMENT VARIATION DUE TO C     CENTROID VARIATION?C  215 IF (SOFA .OR. RAY) THEN        DO 220 N = 1, NV1        IF (CVP(N) .OR. EVP(N)) GO TO 300  220   CONTINUE      ENDIFC             C     UNVARIED ELEMENTC  240 VARLET = .FALSE.      IF (RAY) THEN        DO 245 J = 1, 6  245   ETAT(J) = ETA(J)        CALL THREAD(0,ETAT)      ENDIF      IF (WOOF) THEN        IF (R1P) THEN          DO 251 J = 1, 6  251     COTF(J) = COF(J)          CALL THRED1(R,COTF)        ENDIF        DO 258 J = 1, 6  258   COT(J) = CO(J)        CALL THREAD(0,COT)        IF (NORD1 .GE. 2 .AND. NORD2 .GE. 1) CALL ENRICH(0)      ENDIFC  260 IF (NORD2 .GE. 1) CALL MRR3C      IF (WOOF) THEN        IF (R1P) THEN          IF (DCOV) THEN            DO 291 J = 1, 6  291       COF(J) = COTF(J) + COD(J)          ELSE            DO 292 J = 1, 6  292       COF(J) = COTF(J)          ENDIF        ENDIF        IF (DCOV) THEN          DO 295 J = 1, 6  295     CO(J) = COT(J) + COD(J)        ELSE          DO 296 J = 1, 6  296     CO(J) = COT(J)        ENDIF      ELSE IF (DCOV) THEN        IF (R1P) THEN          DO 297 J = 1, 6  297     COF(J) = COD(J)        ENDIF        DO 298 J = 1, 6  298   CO(J) = COD(J)        SOFA = .TRUE.        NORD1 = NORDX      ENDIF      IF (RAY) THEN        DO 299 J = 1, 6  299   ETA(J) = ETAT(J)      ENDIF      GO TO 800CC     VARIED ELEMENTC  300 VARLET = .TRUE.      IF (R3P) CALL UPDAT3      IF (RAY) THEN        DO 301 J = 1, 6  301   ETAT(J) = ETA(J)        CALL THREAD(0,ETAT)      ENDIF  305 CALL RTORSHC  310 IF (WOOF) THEN        IF (R1P) THEN          DO 312 J = 1, 6  312     COTF(J) = COF(J)          CALL THRED1(R,COTF)        ENDIF        DO 318 J = 1, 6  318   COT(J) = CO(J)        CALL THREAD(0,COT)        IF (NORD1 .GE. 2 .AND. NORD2 .GE. 1) CALL ENRICH(3)      ENDIFCC     R TIMES DERIVATIVE OF ACCUMULATED R2C      DO 380 N = 1, NV1      NV2 = N      IF (R2VP(N) .AND. NORD2 .GE. 1) CALL MRR2VC      IF (CVP(N) .OR. EVP(N)) CALL TWITCH      IF (CVP(N) .AND. NORD1 .GE. 2 .AND. NORD2 .GE. 1)     1    CALL MRTR2  380 CONTINUECC     DERIVATIVE OF R TIMES ACCUMULATED R2 C  400 DO 590 JV = 1, NVTYPE      NV2 = VARST(JV)      DPARM = 1.0      IF (NV2 .EQ. 0) GO TO 590      IF (NV2 .LT. 0) DPARM = - 1.0      NVP = 1      IF (NV2 .EQ. 99) NVP = NV3      NVPART = NV2      DO 580 JP = 1, NVP      IF (NVPART .EQ. 99) THEN        NV2 = JP        IADR = IDATA(I + IPTOJ(JV))        DPARM = DATA(IADR + JP)        IF (DPARM .EQ. 0.0) GO TO 580      ENDIFC      CALL MVZEROC  420 NV1 = MAX0(NV1,IABS(NV2))      CALL PARTLS      NV2 = IABS(NV2)C  440 IF (RAY) THEN        DO 442 J = 1, 6  442   ETAS(J) = ETA(J)        CALL THREAD(1,ETAS)        IF (.NOT. EVP(NV2)) THEN          DO 443 J = 1, 6  443     ETAV(J,NV2) = ETAS(J) + CODV(J)          EVP(NV2) = .TRUE.        ELSE          DO 448 J = 1, 6  448     ETAV(J,NV2) = ETAV(J,NV2) + ETAS(J) + CODV(J)        ENDIF      ENDIFC  450 IF (WOOF) THEN        DO 452 J = 1, 6  452   COSS(J) = CO(J)        CALL THREAD(1,COSS)        IF (.NOT. CVP(NV2)) THEN          DO 453 J = 1, 6  453     COV(J,NV2) = COSS(J)          CVP(NV2) = .TRUE.        ELSE          DO 458 J = 1, 6  458     COV(J,NV2) = COV(J,NV2) + COSS(J)        ENDIF        IF (DCOV) THEN          DO 460 J = 1, 6  460     COV(J,NV2) = COV(J,NV2) + CODV(J)        ENDIFC        IF (NORD1 .GE. 2 .AND. NORD2 .GE. 1) CALL ENRICH(1)C      ELSE        IF (DCOV) THEN          DO 475 J = 1, 6  475     COV(J,NV2) = CODV(J)          CVP(NV2) = .TRUE.        ENDIF      ENDIFC      IF (NORD2 .GE. 1) THEN        CALL MRVRC2        R2VP(NV2) = .TRUE.      ENDIF      LCV(NV2) = LCV(NV2) + LVC  580 CONTINUE  590 CONTINUECC     ACCUMULATED DERIVATIVE OF R2 MATRIXC           DO 620 N = 1, NV1      IF (R2VP(N)) THEN        DO 610 JK = 1, 36        R2VL(JK,N) = R2VSL(JK,N)  610   CONTINUE      ENDIF   620 CONTINUE  CC     ACCUMULATED R2 MATRIXC  650 IF (NWK .NE. 1) GO TO 810      IF (RAY) THEN        DO 655 J = 1, 6  655   ETA(J) = ETAT(J) + COD(J)      ENDIF      IF (WOOF) THEN        IF (R1P) THEN          DO 662 J = 1, 6  662     COF(J) = COTF(J)        ENDIF        DO 667 J = 1, 6  667   CO(J) = COT(J) + COD(J)      ELSE        IF (DCOV) THEN          IF (R1P) THEN            DO 668 J = 1, 6  668       COF(J) = COD(J)          ENDIF          DO 669 J = 1, 6  669     CO(J) = COD(J)          SOFA = .TRUE.          NORD1 = NORDX        ENDIF      ENDIFC  670 IF (NORD2 .GE. 1) THEN        CALL RSHTOR        CALL MRR2      ENDIFCC     ADVANCE TO NEXT ELEMENTC  800 IF (ALIGN) THEN        CALL ADVANC(2)        IF (FLUSHL) GO TO 810        CALL ADVANC(3)        IF (FLUSHL) GO TO 810      ENDIF      IF (.NOT. VARLET) R3P = .TRUE.      IF (VARLET) R2P = .TRUE.      R0P = .TRUE.  808 IF (LAY) CALL GROPE  810 RETURN      END